export const meta = {
  name: 'dreaming-check',
  description: 'ClaudeDream health check: one checker per batch of memory files; reports only, changes nothing',
  phases: [
    { title: 'Check', detail: 'one dreaming:checker per batch of about 8 memory files, all batches in parallel (at most 16 at a time)' },
  ],
}

// Generated by check.py start: every batch of memory files and where its evidence is.
// A checker that fails is recorded without a result and does not stop the run; check.py finish
// lists its files as not checked.
const PLAN = __PLAN__

const VERDICT = {
  type: 'object',
  properties: {
    entries: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          file: { type: 'string' },
          verdict: { type: 'string', enum: ['valid', 'possibly_stale', 'wrong', 'conflict', 'unknown'] },
          reason: { type: 'string' },
          evidence: {
            type: 'array',
            items: { type: 'object', properties: { source: { type: 'string' }, quote: { type: 'string' } }, required: ['source', 'quote'] },
          },
          correction: {
            type: 'object',
            properties: { new_value: { type: 'string' }, date: { type: 'string' }, source: { type: 'string' } },
          },
          stale_note: { type: 'string' },
        },
        required: ['file', 'verdict', 'reason', 'evidence'],
      },
    },
  },
  required: ['entries'],
}

function checkTask(b) {
  return [
    `Check these memory files in the memory directory ${b.snapshot}:`,
    ...b.files.map(f => `- ${f}`),
    `The project's root directory: ${b.roots.length ? b.roots.join(', ') : '(none found)'}`,
    `The project's sessions, as plain-text transcript exports: ${b.transcripts.length ? b.transcripts.join(', ') : '(none)'}`,
    `The project's git history: ${b.context}`,
    `Today is ${b.today}. Give each file a verdict with evidence, as your instructions say, and return one entry per file in this order.`,
  ].join('\n')
}

const results = await parallel(PLAN.batches.map(b => () =>
  agent(checkTask(b), { agentType: 'dreaming:checker', label: `check ${b.id}`, phase: 'Check', schema: VERDICT })))
const failed = PLAN.batches.filter((b, k) => !results[k]).map(b => b.id)
log(`checked ${PLAN.batches.length - failed.length} of ${PLAN.batches.length} batches`)
return { batches: PLAN.batches.length, failed }
